def word_pattern(pattern: str, text: str) -> bool:
    words = text.split()
    if len(pattern) != len(words):
        return False
    mapping = {}
    used_words = set()
    for p, w in zip(pattern, words):
        if p not in mapping:
            if w in used_words:
                return False
            mapping[p] = w
            used_words.add(w)
        elif mapping[p] != w:
            return False
    return True

