    results = {}

    # Iterate over each device
    for device in devices:
        # Check if the primary IP address is already in use
        if device['primary_ip'] in primary_ips:
            # If it is, mark all devices with this IP address as False
            for d in devices:
                if d['primary_ip'] == device['primary_ip']:
                    results[d['name']] = False
            break
        else:
            # If not, add the primary IP address to the set
            primary_ips.add(device['primary_ip'])

            # Initialize a flag to indicate if the primary IP address is in any network
            in_network = False

            # Iterate over each network the device can connect to
            for network in device['networks']:
                # Create an IP network object from the network CIDR notation
                ip_network = ipaddress.ip_network(network, strict=False)

                # Check if the primary IP address is in the network
                if ipaddress.ip_address(device['primary_ip']) in ip_network:
