def recommend(users, movies):
    # Calculate the average rating for each movie across all users
    movie_ratings = {movie: 0 for movie in movies}
    for user in users:
        for movie, rating in user['ratings'].items():
            movie_ratings[movie] += rating
    for movie in movie_ratings:
        movie_ratings[movie] /= len(users)

    # For each user, recommend the movie with the highest average rating that the user has not already watched
    recommendations = {}
    for user in users:
        recommended_movie = max([movie for movie in movies if movie not in user['ratings']], key=lambda movie: movie_ratings[movie])
        recommendations[user['id']] = recommended_movie

    return recommendations

