def find_reachable_nodes(graph, source):
    if source not in graph:
        return set()
    stack = [source]
    visited = set()
    reachable_nodes = set()

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            reachable_nodes.add(node)
            for neighbor in graph[node]:
                stack.append(neighbor)

    return reachable_nodes

